             placeholder="jane@example.com"
             required
           >
           <p class="error-message" id="emailError" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             placeholder="(555) 123-4567"
           >
           <p class="helper-text">Optional. Use a 10-digit US number, for example (555) 123-4567.</p>
           <p class="error-message" id="phoneError" aria-live="polite"></p>
         </div>

         <button type="submit">Submit</button>
         <p class="success-message" id="successMessage" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("supportForm");
     const fields = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullNameError"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }

           if (value.trim().length < 2) {
             return "Enter your full name.";
           }

           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("emailError"),
         validate(value) {
           const trimmed = value.trim();
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

           if (!trimmed) {
             return "Email address is required.";
           }

           if (!emailPattern.test(trimmed)) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phoneError"),
         validate(value) {
           const trimmed = value.trim();
           const phonePattern = /^(?:\+1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;

           if (!trimmed) {
             return "";
           }

           if (!phonePattern.test(trimmed)) {
             return "Enter a valid phone number in the format (555) 123-4567.";
           }

           return "";
         }
       }
     };

     const successMessage = document.getElementById("successMessage");

     function setFieldError(fieldName, message) {
       const field = fields[fieldName];
       const wrapper = field.input.closest(".form-field");

       field.error.textContent = message;
       wrapper.classList.toggle("has-error", Boolean(message));
       field.input.setAttribute("aria-invalid", String(Boolean(message)));
     }

     function validateField(fieldName) {
       const field = fields[fieldName];
       const message = field.validate(field.input.value);
       setFieldError(fieldName, message);
       return !message;
     }

     Object.keys(fields).forEach((fieldName) => {
       const { input } = fields[fieldName];

       input.addEventListener("blur", () => validateField(fieldName));
       input.addEventListener("input", () => {
         if (fields[fieldName].error.textContent) {
           validateField(fieldName);
         }

         successMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       successMessage.textContent = "";

       const invalidField = Object.keys(fields).find((fieldName) => !validateField(fieldName));

       if (invalidField) {
         fields[invalidField].input.focus();
         return;
       }

       successMessage.textContent = "Thanks! Your support request is ready to be reviewed.";
       form.reset();
       Object.keys(fields).forEach((fieldName) => setFieldError(fieldName, ""));
     });
   </script>
 </body>
 </html>

')
